def solve(adds):
    class Cart:
        def __init__(self):
            self.items = []

        def add(self, item):
            self.items.append(item)

    carts = {"a": Cart(), "b": Cart()}
    for name, item in adds:
        carts[name].add(item)
    return {"a": list(carts["a"].items), "b": list(carts["b"].items)}
